```js
export async function getPrompt(name, args = {}) {
  const prompt = PROMPTS.find(p => p.name === name);
  if (!prompt) {
    const err = new Error(`Unknown prompt: ${name}`);
    throw err;
  }
  // Validate args
  const known = new Set(prompt.arguments.map(a => a.name));
  for (const key of Object.keys(args)) {
    if (!known.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  for (const arg of prompt.arguments) {
    if (arg.required) {
      const val = args[arg.name];
      if (val === undefined || val === null || (typeof val === 'string' && val.trim() === '')) {
        throw new Error(`Missing or empty required argument: ${arg.name}`);
      }
    }
  }
  ...
}
