const PROMPTS = [
  {
    name: 'deploy_notice',
    description: 'Generate a deployment notice for a service and version.',
    arguments: [
      { name: 'service', description: 'Name of the service being deployed', required: true },
      { name: 'version', description: 'Version being deployed', required: true }
    ]
  }
];

export async function listTools() { return []; }
export async function callTool() { throw new Error('not implemented'); }

export async function listPrompts() {
  return PROMPTS.map(p => ({
    name: p.name,
    description: p.description,
    arguments: p.arguments.map(a => ({ name: a.name, description: a.description, required: !!a.required }))
  }));
}

export async function getPrompt(name, args = {}) {
  const prompt = PROMPTS.find(p => p.name === name);
  if (!prompt) {
    throw new Error(`Unknown prompt: ${name}`);
  }
  const known = new Set(prompt.arguments.map(a => a.name));
  for (const key of Object.keys(args)) {
    if (!known.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  for (const arg of prompt.arguments) {
    const val = args[arg.name];
    if (val === undefined || val === null) {
      throw new Error(`Missing required argument: ${arg.name}`);
    }
    if (typeof val !== 'string') {
      throw new Error(`Argument ${arg.name} must be a string`);
    }
    if (val.trim() === '') {
      throw new Error(`Argument ${arg.name} must not be empty`);
    }
  }
  const { service, version } = args;
  return {
    messages: [
      { role: 'user', content: { type: 'text', text: `Deployment notice: service ${service} version ${version} is being deployed.` } },
      { role: 'assistant', content: { type: 'text', text: `Acknowledged. Deployment notice for ${service} version ${version} recorded.` } }
    ]
  };
}
```

